check_code:
opts={'A':'HR11','B':'IP9','C':'J8','D':'HQ10'}
def nxt(s):
    a,b,n=s[0],s[1],int(s[2:])
    return chr(ord(a)+2)+chr(ord(b)+2)+str(n-3)
r=nxt('GN12')
assert opts['B']==r
assert all(opts[k]!=r for k in 'ACD')

opp={'deride':{'encourage','praise','applaud'}}
opts={'A':'Encourage','B':'Taunt','C':'Jeer','D':'Detest'}
fit=[k for k,v in opts.items() if v.lower() in opp['deride']]
assert fit==['A']
assert opts['A']=='Encourage'
assert all(opts[k]!='Encourage' for k in 'BCD')

syn={'substantial':{'considerable'}}
opts={'A':'Considerable','B':'Venerable','C':'Meager','D':'Scarce'}
f=[k for k,v in opts.items() if v.lower() in syn['substantial']]
assert f==['A']
assert opts['A']=='Considerable'

def enc(w):
    return ''.join(chr(ord(c)+(1 if c in 'AEIOU' else 2)) for c in w)
assert enc('HUSBAND')=='JVUDBPF' and enc('SISTER')=='UJUVFT'
opts={'A':'DJTFPTV','B':'FJPVDTT','C':'DTPVJFT','D':'TFVJTPD'}
r=enc('BROTHER')
assert opts['C']==r
assert all(opts[k]!=r for k in 'ABD')

fixed={1:'D',3:'F',4:'D',6:'F',8:'F',10:'D',12:'F'}
blanks=[2,5,7,9,11]
opts={'A':'DFDDF','B':'DFFDD','C':'FFDFF','D':'FDDFF'}
def ok(o):
    s=dict(fixed)
    for p,c in zip(blanks,o): s[p]=c
    return ''.join(s[i] for i in range(1,13))=='DFF'*4
f=[k for k,v in opts.items() if ok(v)]
assert f==['C']
assert opts['C']=='FFDFF'
